from unittest import TestCase

from arrays_and_strings.find_max_num_vowels_in_a_given_substring_len import Solution

class TestSolution(TestCase):
    def test_max_vowels_1(self):
        sol = Solution()
        self.assertEqual(sol.maxVowels("leetcode", 3), 2)

    def test_max_vowels_1(self):
        sol = Solution()
        self.assertEqual(sol.maxVowels("weallloveyou", 7), 4)
    def test_max_vowels_2(self):
        sol = Solution()
        ts ="";
        self.assertEqual(sol.maxVowels(ts, 3945), 823)

    def test_max_vowels_3(self):
        sol = Solution()
        ts ="zpuerktejfp"
        self.assertEqual(sol.maxVowels(ts, 1), 1)


